spec.expr:
deriv(
  (
    screeps_market_credits
    + on(job, instance)
    (
      (
        0.95 * sum by(job, instance) (
          screeps_resource_amount
          * on(job, instance, resource)
          screeps_resource_sell_value
        )
      )
      or on(job, instance) (0 * screeps_market_credits)
    )
  )[24h:2m]
) * 86400
